import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { Link, Navigate, useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import {
  ArrowRight, CheckCircle2, Github, KeyRound, Loader2, LockKeyhole,
  Mail, ShieldCheck, UserPlus,
} from 'lucide-react';
import { buildFirstPartyAuthorizeUrl } from '../lib/authHandoff';
import { idAuth, type IdAuthProvider } from '../lib/idAuth';

declare global {
  interface Window {
    google?: {
      accounts: { id: {
        initialize: (options: Record<string, unknown>) => void;
        renderButton: (element: HTMLElement, options: Record<string, unknown>) => void;
      } };
    };
  }
}

type Mode = 'login' | 'signup' | 'forgot' | 'reset' | 'mfa' | 'error';

const pathMode = (pathname: string): Mode => {
  if (pathname.startsWith('/signup')) return 'signup';
  if (pathname.startsWith('/forgot-password')) return 'forgot';
  if (pathname.startsWith('/reset-password')) return 'reset';
  if (pathname.startsWith('/mfa')) return 'mfa';
  if (pathname.startsWith('/error')) return 'error';
  return 'login';
};

const loadGoogleIdentity = () => new Promise<void>((resolve, reject) => {
  if (window.google?.accounts.id) { resolve(); return; }
  const existing = document.querySelector<HTMLScriptElement>('script[data-wersee-google-identity]');
  if (existing) {
    existing.addEventListener('load', () => resolve(), { once: true });
    existing.addEventListener('error', () => reject(new Error('Google sign-in could not be loaded.')), { once: true });
    return;
  }
  const script = document.createElement('script');
  script.src = 'https://accounts.google.com/gsi/client';
  script.async = true;
  script.defer = true;
  script.dataset.werseeGoogleIdentity = 'true';
  script.onload = () => resolve();
  script.onerror = () => reject(new Error('Google sign-in could not be loaded.'));
  document.head.appendChild(script);
});

const messageFrom = (error: unknown) => error instanceof Error ? error.message : 'Something went wrong. Try again.';

const inputClass = 'w-full rounded-2xl border border-white/10 bg-black/35 px-4 py-3.5 text-sm text-white outline-none transition placeholder:text-white/25 focus:border-violet-400/60 focus:ring-4 focus:ring-violet-500/10';

const Shell = ({ children, title, subtitle }: { children: ReactNode; title: string; subtitle: string }) => (
  <div className="relative min-h-[100dvh] overflow-hidden bg-[#060608] px-4 py-8 text-white sm:py-12">
    <div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_18%_0%,rgba(124,58,237,0.22),transparent_34%),radial-gradient(circle_at_88%_8%,rgba(37,99,235,0.14),transparent_30%)]" />
    <main className="relative mx-auto w-full max-w-[430px]">
      <Link to="/" className="mx-auto mb-8 flex w-fit items-center gap-3">
        <span className="grid h-11 w-11 place-items-center rounded-[15px] bg-white text-base font-black text-black">W</span>
        <span><strong className="block text-sm">Wersee ID</strong><span className="block text-[10px] text-white/40">One identity. Every Wersee service.</span></span>
      </Link>
      <section className="rounded-[28px] border border-white/10 bg-white/[0.055] p-5 shadow-[0_30px_100px_rgba(0,0,0,0.42)] backdrop-blur-2xl sm:p-7">
        <header className="mb-6 text-center"><h1 className="text-2xl font-black tracking-tight">{title}</h1><p className="mt-2 text-sm leading-6 text-white/45">{subtitle}</p></header>
        {children}
      </section>
      <p className="mt-6 text-center text-[11px] leading-5 text-white/30">Wersee ID protects your identity, sessions and security settings across the Wersee ecosystem.</p>
    </main>
  </div>
);

const Notice = ({ error, children }: { error?: boolean; children: ReactNode }) => (
  <div role={error ? 'alert' : 'status'} className={`rounded-2xl border px-4 py-3 text-sm ${error ? 'border-red-400/20 bg-red-400/10 text-red-200' : 'border-emerald-400/20 bg-emerald-400/10 text-emerald-200'}`}>{children}</div>
);

const SubmitButton = ({ busy, children }: { busy: boolean; children: ReactNode }) => (
  <button disabled={busy} className="flex w-full items-center justify-center gap-2 rounded-full bg-white px-5 py-3.5 text-sm font-bold text-black transition hover:bg-white/90 disabled:cursor-wait disabled:opacity-55">
    {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowRight className="h-4 w-4" />}{children}
  </button>
);

export const WerseeIdAuth = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const mode = pathMode(location.pathname);
  const redirect = params.get('redirect') || params.get('returnUrl') || params.get('authReturn') || 'https://www.wersee.com/workspace';
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(params.get('notice') === 'check-email' ? 'Check your inbox to confirm your Wersee account.' : null);
  const [providers, setProviders] = useState<IdAuthProvider[]>([]);
  const googleTarget = useRef<HTMLDivElement | null>(null);
  const [mfa, setMfa] = useState<{ factorId: string; challengeId: string } | null>(null);
  const [mfaCode, setMfaCode] = useState('');

  const googleProvider = useMemo(() => providers.find((item) => item.id === 'google' && item.enabled), [providers]);
  const handoffAuthorizeUrl = useMemo(() => (
    params.get('handoff') === '1' ? buildFirstPartyAuthorizeUrl(params) : null
  ), [params]);
  const finishSignIn = (fallback: string) => window.location.assign(handoffAuthorizeUrl || fallback);

  useEffect(() => {
    document.title = mode === 'signup' ? 'Create your Wersee ID' : mode === 'forgot' ? 'Recover your Wersee ID' : mode === 'reset' ? 'Reset your Wersee password' : mode === 'mfa' ? 'Verify your Wersee ID' : 'Sign in to Wersee ID';
  }, [mode]);

  useEffect(() => {
    if (!['login', 'signup'].includes(mode)) return;
    void idAuth.providers().then((data) => setProviders(data.providers)).catch(() => setProviders([]));
  }, [mode]);

  useEffect(() => {
    if (mode !== 'login' || !handoffAuthorizeUrl) return;
    let active = true;
    void idAuth.me().then(() => {
      if (active) window.location.assign(handoffAuthorizeUrl);
    }).catch(() => {});
    return () => { active = false; };
  }, [handoffAuthorizeUrl, mode]);

  useEffect(() => {
    if (!googleProvider?.clientId || !googleTarget.current || !['login', 'signup'].includes(mode)) return;
    let active = true;
    void Promise.all([loadGoogleIdentity(), idAuth.googleContext()]).then(([, context]) => {
      if (!active || !window.google?.accounts.id || !googleTarget.current) return;
      window.google.accounts.id.initialize({
        client_id: googleProvider.clientId,
        nonce: context.nonce,
        auto_select: false,
        cancel_on_tap_outside: true,
        callback: (result: { credential?: string }) => {
          if (!result.credential) return;
          setBusy(true); setError(null);
          void idAuth.google(result.credential, redirect)
            .then((data) => { finishSignIn(data.redirect); })
            .catch((nextError) => setError(messageFrom(nextError)))
            .finally(() => setBusy(false));
        },
      });
      googleTarget.current.innerHTML = '';
      window.google.accounts.id.renderButton(googleTarget.current, {
        type: 'standard', theme: 'filled_black', size: 'large', shape: 'pill',
        text: 'continue_with', width: Math.min(374, googleTarget.current.clientWidth),
      });
    }).catch((nextError) => { if (active) setError(messageFrom(nextError)); });
    return () => { active = false; };
  }, [googleProvider?.clientId, handoffAuthorizeUrl, mode, redirect]);

  useEffect(() => {
    if (mode !== 'mfa') return;
    setBusy(true); setError(null);
    void idAuth.mfa().then(async (data) => {
      const factor = [...data.factors.totp, ...data.factors.phone].find((item) => item.status === 'verified')
        || data.factors.totp[0] || data.factors.phone[0];
      if (!factor) { navigate('/security?notice=mfa-not-enrolled', { replace: true }); return; }
      const challenge = await idAuth.mfaChallenge(factor.id);
      setMfa({ factorId: factor.id, challengeId: challenge.challenge_id });
    }).catch((nextError) => setError(messageFrom(nextError))).finally(() => setBusy(false));
  }, [mode, navigate]);

  const submitCredentials = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError(null); setNotice(null);
    try {
      if (mode === 'signup') {
        if (password !== confirm) throw new Error('The passwords do not match.');
        const data = await idAuth.signup({ email, password, display_name: displayName, redirect });
        if (data.confirmation_required) setNotice('Check your inbox to confirm your Wersee account.');
        else finishSignIn(data.redirect);
      } else {
        const data = await idAuth.login({ email, password, redirect });
        finishSignIn(data.redirect);
      }
    } catch (nextError) { setError(messageFrom(nextError)); }
    finally { setBusy(false); }
  };

  const submitRecovery = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError(null);
    try { await idAuth.recover(email); setNotice('If an account exists for that address, Wersee has sent a recovery email.'); }
    catch (nextError) { setError(messageFrom(nextError)); }
    finally { setBusy(false); }
  };

  const submitReset = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError(null);
    try {
      if (password !== confirm) throw new Error('The passwords do not match.');
      const data = await idAuth.resetPassword(password);
      window.location.assign(data.redirect);
    } catch (nextError) { setError(messageFrom(nextError)); }
    finally { setBusy(false); }
  };

  const submitMfa = async (event: FormEvent) => {
    event.preventDefault();
    if (!mfa) return;
    setBusy(true); setError(null);
    try {
      const data = await idAuth.mfaVerify(mfa.factorId, mfa.challengeId, mfaCode, redirect);
      finishSignIn(data.redirect);
    } catch (nextError) { setError(messageFrom(nextError)); }
    finally { setBusy(false); }
  };

  const startOAuth = async (provider: 'azure' | 'github') => {
    setBusy(true); setError(null);
    const callbackRedirect = handoffAuthorizeUrl ? window.location.href : redirect;
    try { const data = await idAuth.oauthStart(provider, callbackRedirect); window.location.assign(data.url); }
    catch (nextError) { setError(messageFrom(nextError)); setBusy(false); }
  };

  if (location.pathname === '/auth' || location.pathname === '/signin' || location.pathname === '/sign-in' || location.pathname === '/log-in') {
    return <Navigate to={`/login${location.search}`} replace />;
  }

  if (mode === 'error') return <Shell title="This link no longer works" subtitle="The authentication request is invalid, expired, or has already been used."><div className="space-y-4"><Notice error>Start a new sign-in or recovery request. No account data was changed.</Notice><Link to="/login" className="flex w-full items-center justify-center gap-2 rounded-full bg-white px-5 py-3 text-sm font-bold text-black">Back to sign in <ArrowRight className="h-4 w-4" /></Link></div></Shell>;

  if (mode === 'forgot') return <Shell title="Recover your account" subtitle="Wersee will send a secure, branded recovery link if the account exists."><form onSubmit={submitRecovery} className="space-y-4"><label className="block space-y-2 text-xs font-semibold text-white/55">Email address<input type="email" autoComplete="email" required className={inputClass} value={email} onChange={(event) => setEmail(event.target.value)} /></label>{error && <Notice error>{error}</Notice>}{notice && <Notice>{notice}</Notice>}<SubmitButton busy={busy}>Send recovery email</SubmitButton><Link to="/login" className="block text-center text-xs font-semibold text-white/50 hover:text-white">Back to sign in</Link></form></Shell>;

  if (mode === 'reset') return <Shell title="Choose a new password" subtitle="This changes the password for your complete Wersee account."><form onSubmit={submitReset} className="space-y-4"><input type="password" autoComplete="new-password" minLength={8} required placeholder="New password" className={inputClass} value={password} onChange={(event) => setPassword(event.target.value)} /><input type="password" autoComplete="new-password" minLength={8} required placeholder="Confirm new password" className={inputClass} value={confirm} onChange={(event) => setConfirm(event.target.value)} />{error && <Notice error>{error}</Notice>}<SubmitButton busy={busy}>Update password</SubmitButton></form></Shell>;

  if (mode === 'mfa') return <Shell title="Two-factor verification" subtitle="Enter the current code from your authenticator app to finish signing in."><form onSubmit={submitMfa} className="space-y-4"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-violet-400/10 text-violet-200"><ShieldCheck className="h-7 w-7" /></div><input inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6,10}" required placeholder="Authentication code" className={`${inputClass} text-center text-lg tracking-[0.35em]`} value={mfaCode} onChange={(event) => setMfaCode(event.target.value.replace(/\D/g, '').slice(0, 10))} />{error && <Notice error>{error}</Notice>}<SubmitButton busy={busy || !mfa}>Verify and continue</SubmitButton></form></Shell>;

  const isSignup = mode === 'signup';
  return <Shell title={isSignup ? 'Create your Wersee ID' : 'Sign in to Wersee'} subtitle={isSignup ? 'One secure account for every Wersee service.' : 'Continue with the same identity across the Wersee ecosystem.'}>
    <div className="space-y-5">
      <div className="space-y-3">
        {googleProvider && <div ref={googleTarget} className="flex min-h-11 w-full items-center justify-center overflow-hidden rounded-full" aria-label="Continue with Google" />}
        {providers.some((item) => item.id === 'azure' && item.enabled) && <button type="button" aria-label="Continue with Microsoft" disabled={busy} onClick={() => void startOAuth('azure')} className="flex w-full items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.06] px-4 py-3 text-sm font-semibold hover:bg-white/10 disabled:opacity-50"><span aria-hidden="true" className="grid grid-cols-2 gap-0.5"><i className="h-1.5 w-1.5 bg-[#f25022]" /><i className="h-1.5 w-1.5 bg-[#7fba00]" /><i className="h-1.5 w-1.5 bg-[#00a4ef]" /><i className="h-1.5 w-1.5 bg-[#ffb900]" /></span>Continue with Microsoft</button>}
        {providers.some((item) => item.id === 'github' && item.enabled) && <button type="button" disabled={busy} onClick={() => void startOAuth('github')} className="flex w-full items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.06] px-4 py-3 text-sm font-semibold hover:bg-white/10 disabled:opacity-50"><Github className="h-4 w-4" />Continue with GitHub</button>}
      </div>
      <div className="flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-white/25"><span className="h-px flex-1 bg-white/10" />or email<span className="h-px flex-1 bg-white/10" /></div>
      <form onSubmit={submitCredentials} className="space-y-4">
        {isSignup && <label className="block space-y-2 text-xs font-semibold text-white/55">Display name<div className="relative"><UserPlus className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" /><input autoComplete="name" maxLength={160} className={`${inputClass} pl-11`} value={displayName} onChange={(event) => setDisplayName(event.target.value)} /></div></label>}
        <label className="block space-y-2 text-xs font-semibold text-white/55">Email address<div className="relative"><Mail className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" /><input type="email" autoComplete="email" required className={`${inputClass} pl-11`} value={email} onChange={(event) => setEmail(event.target.value)} /></div></label>
        <label className="block space-y-2 text-xs font-semibold text-white/55"><span className="flex justify-between">Password{!isSignup && <Link to="/forgot-password" className="text-violet-300 hover:text-violet-200">Forgot password?</Link>}</span><div className="relative"><LockKeyhole className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" /><input type="password" autoComplete={isSignup ? 'new-password' : 'current-password'} minLength={8} required className={`${inputClass} pl-11`} value={password} onChange={(event) => setPassword(event.target.value)} /></div></label>
        {isSignup && <label className="block space-y-2 text-xs font-semibold text-white/55">Confirm password<input type="password" autoComplete="new-password" minLength={8} required className={inputClass} value={confirm} onChange={(event) => setConfirm(event.target.value)} /></label>}
        {error && <Notice error>{error}</Notice>}{notice && <Notice>{notice}</Notice>}
        <SubmitButton busy={busy}>{isSignup ? 'Create Wersee ID' : 'Sign in securely'}</SubmitButton>
      </form>
      <div className="rounded-2xl border border-white/8 bg-black/20 p-3 text-center text-xs text-white/40"><CheckCircle2 className="mr-1.5 inline h-3.5 w-3.5 text-emerald-300" />Your password and session tokens never enter application JavaScript.</div>
      <p className="text-center text-xs text-white/45">{isSignup ? 'Already have a Wersee ID?' : 'New to Wersee?'} <Link to={`${isSignup ? '/login' : '/signup'}?redirect=${encodeURIComponent(redirect)}`} className="font-semibold text-white hover:underline">{isSignup ? 'Sign in' : 'Create an account'}</Link></p>
    </div>
  </Shell>;
};
